    [Fact] public void LegacyMigrationKeepsCanonicalStateWhenLaunchContextChanges(){
        var root=Temp();var legacy=Path.Combine(root,"legacy");var canonical=Path.Combine(root,"canonical");Directory.CreateDirectory(Path.Combine(legacy,"live"));
        File.WriteAllText(Path.Combine(legacy,"live","marker.log"),"first");BridgePaths.MigrateLegacy(legacy,canonical);
        File.WriteAllText(Path.Combine(legacy,"live","marker.log"),"second");BridgePaths.MigrateLegacy(legacy,canonical);
        Assert.Equal("first",File.ReadAllText(Path.Combine(canonical,"live","marker.log")));
    }

    [Fact] public void CanonicalCertificateCannotBeReplacedByConflictingLegacyContext(){
        var root=Temp();var legacyA=Path.Combine(root,"a");var legacyB=Path.Combine(root,"b");var canonical=Path.Combine(root,"canonical");
        Directory.CreateDirectory(legacyA);Directory.CreateDirectory(legacyB);File.WriteAllText(Path.Combine(legacyA,"certificate.dpapi"),"A");File.WriteAllText(Path.Combine(legacyB,"certificate.dpapi"),"B");
        BridgePaths.MigrateLegacy(legacyA,canonical);BridgePaths.MigrateLegacy(legacyB,canonical);Assert.Equal("A",File.ReadAllText(Path.Combine(canonical,"certificate.dpapi")));
    }

    [Fact] public void ExistingCanonicalBundleBlocksLegacyDatabaseImport(){var root=Path.GetDirectoryName(Temp())!;var legacy=Path.Combine(root,"legacy");var canonical=Path.Combine(root,"canonical");Directory.CreateDirectory(canonical);File.WriteAllText(Path.Combine(canonical,"certificate.dpapi"),"canonical");using(var source=new BridgeStore(Path.Combine(legacy,"live","bridge.db"))){File.WriteAllText(Path.Combine(legacy,"certificate.dpapi"),"legacy");BridgePaths.MigrateLegacy(legacy,canonical);}Assert.False(File.Exists(Path.Combine(canonical,"live","bridge.db")));Assert.Equal("canonical",File.ReadAllText(Path.Combine(canonical,"certificate.dpapi")));}

    [Fact] public void LegacyWalDatabaseIsBackedUpAsPartOfMigration(){var root=Path.GetDirectoryName(Temp())!;var legacy=Path.Combine(root,"legacy");var canonical=Path.Combine(root,"canonical");var dbPath=Path.Combine(legacy,"live","bridge.db");string id;using(var source=new BridgeStore(dbPath)){id=source.BridgeId;File.WriteAllText(Path.Combine(legacy,"certificate.dpapi"),"identity");BridgePaths.MigrateLegacy(legacy,canonical);}using var migrated=new BridgeStore(Path.Combine(canonical,"live","bridge.db"));Assert.Equal(id,migrated.BridgeId);}

