    [Fact] public void MigrationCommitCallbackFailureLeavesCanonicalAbsent(){var root=Path.GetDirectoryName(Temp())!;var legacy=Path.Combine(root,"legacy");var canonical=Path.Combine(root,"canonical");Directory.CreateDirectory(legacy);File.WriteAllText(Path.Combine(legacy,"marker.log"),"x");Assert.Throws<InvalidOperationException>(()=>BridgePaths.MigrateLegacy(legacy,canonical,false,()=>false));Assert.False(Directory.Exists(canonical));}
    [Fact] public void ActiveLiveMigrationPreservesConflictingInactiveDemoPairingForExplicitRepair(){var root=Path.GetDirectoryName(Temp())!;var legacy=Path.Combine(root,"legacy");var canonical=Path.Combine(root,"canonical");var liveDb=Path.Combine(legacy,"live","bridge.db");using(var live=new BridgeStore(liveDb)){Pair(live);File.WriteAllText(Path.Combine(legacy,"certificate.dpapi"),"A");File.WriteAllText(Path.Combine(legacy,"live","certificate.dpapi"),"A");using(var demo=new BridgeStore(Path.Combine(legacy,"demo","bridge.db"))){Pair(demo);File.WriteAllText(Path.Combine(legacy,"demo","certificate.dpapi"),"B");BridgePaths.MigrateLegacy(legacy,canonical,activeMode:"live");} }Assert.Equal("A",File.ReadAllText(Path.Combine(canonical,"certificate.dpapi")));Assert.True(File.Exists(Path.Combine(canonical,"migration-conflict-demo.txt")));Assert.Throws<InvalidOperationException>(()=>BridgePaths.EnsureModeIsUsable(canonical,"demo"));BridgePaths.EnsureModeIsUsable(canonical,"live");}

    [Fact] public void StatePreservesUnknownFieldsAndRejectsNewSchema(){
        var path=Temp();using(var store=new BridgeStore(path)){}
        using(var db=new SqliteConnection($"Data Source={path}")){db.Open();using var command=db.CreateCommand();command.CommandText="UPDATE state SET json=json_set(json, '$.futureFlag', json('true'), '$.schemaVersion', 999) WHERE id=1";command.ExecuteNonQuery();}
        Assert.Throws<InvalidOperationException>(()=>new BridgeStore(path));
        using(var db=new SqliteConnection($"Data Source={path}")){db.Open();using var command=db.CreateCommand();command.CommandText="UPDATE state SET json=json_set(json, '$.schemaVersion', 1) WHERE id=1";command.ExecuteNonQuery();}
        using(var store=new BridgeStore(path)){}
        using(var db=new SqliteConnection($"Data Source={path}")){db.Open();using var command=db.CreateCommand();command.CommandText="SELECT json FROM state WHERE id=1";var json=(string)command.ExecuteScalar()!;Assert.Equal(JsonValueKind.True,JsonDocument.Parse(json).RootElement.GetProperty("futureFlag").ValueKind);}
    }

    [Fact] public void CertificateIdentityIsIndependentOfModeAndExecutableDirectory(){
        var root=Path.Combine(Path.GetTempPath(),"bridge-identity",Guid.NewGuid().ToString());
        var live=Path.Combine(root,"live");var demo=Path.Combine(root,"demo");
        Assert.Equal(Path.Combine(root,"certificate.dpapi"),BridgeIdentityFiles.CertificatePath(root));
        Assert.Equal(BridgeIdentityFiles.CertificatePath(root),BridgeIdentityFiles.CertificatePath(root+Path.DirectorySeparatorChar));
        Assert.Equal(new[]{Path.Combine(live,"certificate.dpapi"),Path.Combine(demo,"certificate.dpapi")},BridgeIdentityFiles.LegacyCertificatePaths(root,live));
        Assert.Equal(BridgeIdentityFiles.CertificatePath(root),BridgeIdentityFiles.CertificatePath(Path.GetFullPath(root)));
    }

    [Fact] public void StoredBridgeIdentityRejectsSilentCertificateReplacement(){
        var path=Temp();var original=new string('A',64);var replacement=new string('B',64);
        using(var store=new BridgeStore(path)){Assert.True(store.CanCreateCertificate);store.ConfirmCertificateIdentity(original);Assert.False(store.CanCreateCertificate);store.ConfirmCertificateIdentity(original.ToLowerInvariant());}
        using(var store=new BridgeStore(path)){
            store.ConfirmCertificateIdentity(original);
            var error=Assert.Throws<InvalidOperationException>(()=>store.ConfirmCertificateIdentity(replacement));
            Assert.Contains("will not silently replace",error.Message);
        }
    }

