    [Fact] public void ExplicitAmendmentSupersedesInventoryBlockedPredecessor(){
        using var store=new BridgeStore(Temp());var pair=Pair(store);var original=Link(store,pair) with{ClientJourneyId=Guid.NewGuid().ToString()};
        var old=store.Queue(pair.PairingId,original);store.Reconcile(Snapshot(free:0),Planner);
        Assert.Equal(JobState.Blocked,Assert.Single(store.Jobs(pair.PairingId)).State);
        store.Queue(pair.PairingId,original with{ClientJourneyId=Guid.NewGuid().ToString(),SupersedesJourneyId=original.ClientJourneyId,Deck=original.Deck with{Revision=2}});
        Assert.Equal(JobState.Superseded,store.Jobs(pair.PairingId).Single(x=>x.JobId==old.JobId).State);
        Assert.Single(store.Jobs(pair.PairingId),x=>x.State==JobState.Queued);
    }
    [Fact] public void AmendmentBeforeOriginalArrivalTombstonesOriginal(){
        using var store=new BridgeStore(Temp());var pair=Pair(store);var original=Link(store,pair) with{ClientJourneyId=Guid.NewGuid().ToString()};
        var next=original with{ClientJourneyId=Guid.NewGuid().ToString(),SupersedesJourneyId=original.ClientJourneyId,Deck=original.Deck with{Revision=2}};
        var accepted=store.Queue(pair.PairingId,next);Assert.Equal(JobState.Queued,accepted.State);
        Assert.Throws<BridgeException>(()=>store.Queue(pair.PairingId,original));Assert.Single(store.Jobs(pair.PairingId));
    }
