    public void CompatibleCasesAllowLargerCapacity(int phoneCase,int pcCase,bool allowed){var s=Snapshot();s=s with{Arsenals=s.Arsenals.Select(x=>x.Slot==1?x with{CaseCapacity=pcCase}:x).ToArray()};var p=Plan(Deck() with{CaseCapacity=phoneCase},s);Assert.Equal(allowed,!p.Blockers.Any(x=>x.Code=="CaseMismatch"));Assert.Equal(pcCase,s.Arsenals[0].CaseCapacity);}
    [Fact] public void OccupiedCaseRequiresExplicitFingerprintBoundOverwrite(){using var s=new BridgeStore(Temp());var p=Pair(s);var r=new LinkRequest(Guid.NewGuid().ToString(),Guid.NewGuid().ToString(),"p",1,1,"target",true);Assert.Throws<BridgeException>(()=>s.Link(p.PairingId,r with{ConfirmedFingerprint="stale"},Snapshot()));Assert.True(s.Link(p.PairingId,r,Snapshot()).Active);}
    [Fact] public void IdenticalClaimDoesNotGrantOverwriteAndStillChecksOwnership(){
        using var store=new BridgeStore(Temp());var owner=Pair(store);var snapshot=Snapshot();var target=snapshot.Arsenals[0];
        var proof=new DeckSpec(Guid.NewGuid().ToString(),1,target.Name,target.SkillIds.Reverse().ToArray(),target.CaseCapacity,"retail_2017_full");
        var request=new LinkRequest(Guid.NewGuid().ToString(),proof.DeckId,"p",target.Slot,1,target.Fingerprint!,IdenticalDeck:proof);
        Assert.Throws<BridgeException>(()=>store.Link(owner.PairingId,request with{IdenticalDeck=proof with{Name="Different"}},snapshot));
        Assert.True(store.Link(owner.PairingId,request,snapshot).Active);
        var other=Pair(store);Assert.Throws<BridgeException>(()=>store.Link(other.PairingId,request with{LinkId=Guid.NewGuid().ToString()},snapshot));
        Assert.Throws<BridgeException>(()=>store.Link(owner.PairingId,request with{ConfirmedFingerprint="stale"},snapshot));
        Assert.Empty(store.Jobs(owner.PairingId));
    }
