    [Fact] public void PairingRequiresSecretAndIsSingleUse(){using var s=new BridgeStore(Temp());var p=s.BeginPairing("https://localhost","cert");Assert.Throws<BridgeException>(()=>s.Pair(new("bad","phone")));var pair=s.Pair(new(p.BootstrapSecret,"phone"));Assert.Equal(pair.PairingId,s.Authenticate("Bearer "+pair.Token));Assert.Throws<BridgeException>(()=>s.Pair(new(p.BootstrapSecret,"phone")));s.Revoke(pair.PairingId);Assert.Throws<BridgeException>(()=>s.Authenticate("Bearer "+pair.Token));}
    [Fact] public void PairingSameVerifiedPhoneIdentityRotatesTokenAndKeepsOwnership(){using var s=new BridgeStore(Temp());var firstPayload=s.BeginPairing("https://localhost","cert");var first=s.Pair(new(firstPayload.BootstrapSecret,"Oppo","stable-phone"));var request=Link(s,first);var secondPayload=s.BeginPairing("https://localhost","cert");var second=s.Pair(new(secondPayload.BootstrapSecret,"Oppo restored","stable-phone"));Assert.Equal(first.PairingId,second.PairingId);Assert.Throws<BridgeException>(()=>s.Authenticate("Bearer "+first.Token));Assert.Equal(first.PairingId,s.Authenticate("Bearer "+second.Token));Assert.Equal(first.PairingId,Assert.Single(s.Links(first.PairingId)).PairingId);}
    [Fact] public void QueueSurvivesRestartAndRetriesAreIdempotent(){var path=Temp();PairResponse pair;QueueRequest r;string id;string bridge;using(var s=new BridgeStore(path)){pair=Pair(s);r=Link(s,pair);id=s.Queue(pair.PairingId,r).JobId;bridge=s.BridgeId;Assert.Equal(id,s.Queue(pair.PairingId,r).JobId);}using(var s=new BridgeStore(path)){Assert.Equal(bridge,s.BridgeId);Assert.Equal(pair.PairingId,s.Authenticate("Bearer "+pair.Token));Assert.Equal(r.Deck.DeckId,Assert.Single(s.Jobs(pair.PairingId)).DeckId);Assert.Equal(id,s.Queue(pair.PairingId,r).JobId);}}
    [Fact] public void ProfileImportClaimsEveryTargetAtomicallyAndIsIdempotent(){using var store=new BridgeStore(Temp());var pair=Pair(store);var raw=Snapshot();var decks=raw.Arsenals.Select(x=>x with{ContentFingerprint=Planner.CardContentFingerprint(x.SkillIds)}).ToArray();var snapshot=raw with{Arsenals=decks,GameProfileSlot=1,GameProfileDisplayName="final"};var request=new ProfileImportRequest(Guid.NewGuid().ToString(),"p",decks.Select(x=>new ProfileImportDeck(Guid.NewGuid().ToString(),Guid.NewGuid().ToString(),x.Slot,x.Fingerprint!,x.ContentFingerprint!)).ToArray());var first=store.ImportProfile(pair.PairingId,request,snapshot);Assert.Equal(2,first.Links.Count);Assert.All(first.Links,x=>Assert.True(x.Active));var retry=store.ImportProfile(pair.PairingId,request,snapshot);Assert.True(retry.AlreadyApplied);Assert.Equal(first.Links,retry.Links);var changed=request with{ImportId=Guid.NewGuid().ToString(),Decks=request.Decks.Skip(1).ToArray()};Assert.Throws<BridgeException>(()=>store.ImportProfile(pair.PairingId,changed,snapshot));Assert.Equal(2,store.Links(pair.PairingId).Length);}
    [Fact] public void RevisionSupersessionAndPayloadMismatch(){using var s=new BridgeStore(Temp());var p=Pair(s);var r=Link(s,p);var j=s.Queue(p.PairingId,r);Assert.Throws<BridgeException>(()=>s.Queue(p.PairingId,r with{Deck=r.Deck with{Name="renamed locally"}}));Assert.Throws<BridgeException>(()=>s.Queue(p.PairingId,r with{Deck=r.Deck with{CaseCapacity=3}}));s.Queue(p.PairingId,r with{Deck=r.Deck with{Revision=2}});Assert.Contains(s.Jobs(p.PairingId),x=>x.State==JobState.Superseded);Assert.Equal(2,s.Jobs(p.PairingId).Length);}
    [Fact] public void OwnershipAndUnlinkCancel(){using var s=new BridgeStore(Temp());var p=Pair(s);var r=Link(s,p);var j=s.Queue(p.PairingId,r);var other=Pair(s);Assert.Empty(s.Jobs(other.PairingId));Assert.Throws<BridgeException>(()=>s.Cancel(other.PairingId,j.JobId));Assert.Throws<BridgeException>(()=>s.Link(other.PairingId,new(Guid.NewGuid().ToString(),Guid.NewGuid().ToString(),"p",1,1,"target"),Snapshot()));s.Unlink(p.PairingId,r.LinkId);Assert.Equal(JobState.Cancelled,Assert.Single(s.Jobs(p.PairingId)).State);Assert.Throws<BridgeException>(()=>s.Queue(p.PairingId,r));}
    [Fact] public void LinkRenewalDoesNotRestampCancelledJobsAndSupersedesActiveGeneration(){using var s=new BridgeStore(Temp());var p=Pair(s);var r=Link(s,p);var cancelled=s.Queue(p.PairingId,r);s.Cancel(p.PairingId,cancelled.JobId);var cancelledAt=Assert.Single(s.Jobs(p.PairingId),x=>x.JobId==cancelled.JobId).UpdatedAt;var active=s.Queue(p.PairingId,r with{Deck=r.Deck with{Revision=2},ClientJourneyId=Guid.NewGuid().ToString()});var renewed=s.Link(p.PairingId,new(r.LinkId,r.Deck.DeckId,r.ProfileKey,r.TargetSlot,2,r.ConfirmedFingerprint),Snapshot(targetCopies:0));var jobs=s.Jobs(p.PairingId);Assert.Equal(cancelledAt,jobs.Single(x=>x.JobId==cancelled.JobId).UpdatedAt);Assert.Equal(JobState.Cancelled,jobs.Single(x=>x.JobId==cancelled.JobId).State);Assert.Equal(JobState.Superseded,jobs.Single(x=>x.JobId==active.JobId).State);Assert.Equal("Replaced by a renewed PC link.",jobs.Single(x=>x.JobId==active.JobId).Reason);}
    [Fact] public void ExplicitCancelUsesUserInitiatedCopy(){using var s=new BridgeStore(Temp());var p=Pair(s);var j=s.Queue(p.PairingId,Link(s,p));var cancelled=s.Cancel(p.PairingId,j.JobId);Assert.True((bool)cancelled.GetType().GetProperty("cancelled")!.GetValue(cancelled)!);Assert.Equal("Cancelled by you before the PC arsenal was updated.",cancelled.GetType().GetProperty("reason")!.GetValue(cancelled));Assert.Equal("Cancelled by you before the PC arsenal was updated.",Assert.Single(s.Jobs(p.PairingId)).Reason);}
