    [Fact] public void JobWaitingNoticesAreNormalizedDeduplicatedAndDurable(){
        var path=Temp();string pairing;
        using(var s=new BridgeStore(path)){
            var p=Pair(s);pairing=p.PairingId;s.Queue(pairing,Link(s,p));s.Reconcile(Snapshot() with{GameRunning=false},Planner);
            s.RecordJobNotices();var waiting=Assert.Single(s.ClaimNotices());Assert.Contains("WaitingForGame",waiting.Id);Assert.Contains("Waiting for Phantom Dust",waiting.Message);
            s.RecordJobNotices();Assert.Empty(s.ClaimNotices());
            s.ExecuteOneNormalJob(new FixedReader(Snapshot() with{WriteSupported=true,GameForeground=false}),Planner,(_,_)=>new(JobState.Completed));
            s.RecordJobNotices();var readiness=Assert.Single(s.ClaimNotices());Assert.Contains("WaitingForReadiness",readiness.Id);
            s.RecordJobNotices();Assert.Empty(s.ClaimNotices());
        }
        using(var restarted=new BridgeStore(path)){restarted.RecordJobNotices();Assert.Empty(restarted.ClaimNotices());Assert.Single(restarted.Jobs(pairing));}
    }
    [Fact] public void JobBlockedRecoveryAndCompletionNoticesUseOneStableMilestoneEach(){
        using(var blocked=new BridgeStore(Temp())){var p=Pair(blocked);blocked.Queue(p.PairingId,Link(blocked,p));blocked.Reconcile(Snapshot(free:0),Planner);blocked.RecordJobNotices();var notice=Assert.Single(blocked.ClaimNotices());Assert.Contains("Blocked",notice.Id);blocked.RecordJobNotices();Assert.Empty(blocked.ClaimNotices());}
