    [Fact] public void InitialFocusWaitAutomaticallyResumesWithoutPretendingAWriteOccurred(){
        using var store=new BridgeStore(Temp());var pair=Pair(store);store.Queue(pair.PairingId,Link(store,pair));
        var snapshot=Snapshot() with{WriteSupported=true,GameForeground=false};var writes=0;var probes=0;
        for(var i=0;i<2;i++)store.ExecuteOneNormalJob(new FixedReader(snapshot),Planner,(_,_,_)=>{writes++;return new(JobState.Completed);},()=>{probes++;return true;});
        Assert.Equal(0,writes);Assert.Equal(0,probes);Assert.Equal("WaitingForGame",Assert.Single(store.Jobs(pair.PairingId)).Phase);
        store.ExecuteOneNormalJob(new FixedReader(snapshot with{GameForeground=true}),Planner,(_,_,_)=>{writes++;return new(JobState.Completed);},()=>true);
        Assert.Equal(1,writes);Assert.Equal(JobState.Completed,Assert.Single(store.Jobs(pair.PairingId)).State);
    }
