    [Fact] public void AwaitingSaveRejectsSuccessorAndPreservesOriginalEvidence(){
        using var s=new BridgeStore(Temp());var p=Pair(s);var d=Deck() with{Name="First",Revision=1};var link=new LinkRequest(Guid.NewGuid().ToString(),d.DeckId,"p",2,1,"other");var snap=WritableSnapshot(2,"other");s.Link(p.PairingId,link,snap);
        var first=s.Queue(p.PairingId,new("p",2,"other",d,"other",link.LinkId,1));
        s.ExecuteOneNormalJob(new FixedReader(snap),Planner,(request,_)=>new WriteResult(JobState.AppliedAwaitingGameSave,new(new("Old",snap.Arsenals[1].SkillIds,2),new(request.Deck.Name,request.Deck.SkillIds,2))));
        var applied=Assert.Single(s.Jobs(p.PairingId));Assert.Equal(JobState.AppliedAwaitingGameSave,applied.State);Assert.Equal("Old",applied.Changes!.Before.Name);
        var expected=Planner.TargetFingerprint(2,"First",2,d.SkillIds);
        Assert.Throws<BridgeException>(()=>s.Queue(p.PairingId,new("p",2,expected,d with{Name="Second",Revision=2},expected,link.LinkId,1,Guid.NewGuid().ToString())));
        Assert.Equal(first.JobId,Assert.Single(s.Jobs(p.PairingId)).JobId);
    }
