    private sealed class FixedReader(Snapshot snapshot):IPhantomDustProfileReader { public Snapshot Read()=>snapshot; }
    private static Snapshot WritableSnapshot(int slot,string fingerprint)=>new("p","snapshot",Wire.Now,true,true,true,true,false,[new(1,"Unrelated",2,Enumerable.Repeat("000",30).ToArray(),"other"),new(slot,"Old",2,Enumerable.Repeat("000",30).ToArray(),fingerprint)],new Dictionary<string,int>{{"001",9},{"002",9}},GameProfileDisplayName:"Profile");
}

